<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Snake Game</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: #1a1a1a;
            color: #ffffff;
            font-family: Arial, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        .container {
            text-align: center;
            padding: 20px;
        }

        h1 {
            margin-bottom: 20px;
            font-size: 2em;
        }

        #snake {
            display: block;
            border: 2px solid #00ff00;
            background-color: #0a0a0a;
            margin: 0 auto 20px;
            image-rendering: pixelated;
            image-rendering: crisp-edges;
        }

        .score-display {
            font-size: 1.5em;
            margin-bottom: 20px;
        }

        .controls {
            display: flex;
            gap: 10px;
            justify-content: center;
            flex-wrap: wrap;
        }

        button {
            padding: 10px 20px;
            font-size: 1em;
            background-color: #00ff00;
            color: #000000;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-weight: bold;
            transition: background-color 0.2s;
        }

        button:hover {
            background-color: #00cc00;
        }

        button:active {
            background-color: #009900;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Snake</h1>
        <canvas id="snake" width="400" height="400"></canvas>
        <div class="score-display">Score: <span id="score">0</span></div>
        <div class="controls">
            <button id="start">Start</button>
            <button id="pause">Pause</button>
            <button id="reset">Reset</button>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('snake');
        const ctx = canvas.getContext('2d');
        const scoreDisplay = document.getElementById('score');

        const GRID_W = 20;
        const GRID_H = 20;
        const CELL_SIZE = canvas.width / GRID_W;

        let gameState = {
            snakeBody: [[10, 10], [9, 10], [8, 10]],
            direction: 'right',
            nextDirection: 'right',
            food: [15, 15],
            score: 0,
            alive: true,
            running: false
        };

        let gameLoopId = null;

        function reset() {
            gameState = {
                snakeBody: [[10, 10], [9, 10], [8, 10]],
                direction: 'right',
                nextDirection: 'right',
                food: [15, 15],
                score: 0,
                alive: true,
                running: false
            };
            if (gameLoopId) {
                clearInterval(gameLoopId);
                gameLoopId = null;
            }
            scoreDisplay.textContent = '0';
            draw();
        }

        function setDir(direction) {
            const opposites = {
                'up': 'down',
                'down': 'up',
                'left': 'right',
                'right': 'left'
            };

            if (opposites[direction] !== gameState.direction) {
                gameState.nextDirection = direction;
            }
        }

        function getNewFoodPosition() {
            const occupied = new Set();
            gameState.snakeBody.forEach(([x, y]) => {
                occupied.add(`${x},${y}`);
            });

            let x, y;
            do {
                x = Math.floor(Math.random() * GRID_W);
                y = Math.floor(Math.random() * GRID_H);
            } while (occupied.has(`${x},${y}`));

            return [x, y];
        }

        function setFood(x, y) {
            gameState.food = [x, y];
            draw();
        }

        function tick() {
            if (!gameState.alive) return;

            gameState.direction = gameState.nextDirection;

            const head = gameState.snakeBody[0];
            let newHead;

            switch (gameState.direction) {
                case 'up':
                    newHead = [head[0], head[1] - 1];
                    break;
                case 'down':
                    newHead = [head[0], head[1] + 1];
                    break;
                case 'left':
                    newHead = [head[0] - 1, head[1]];
                    break;
                case 'right':
                    newHead = [head[0] + 1, head[1]];
                    break;
            }

            if (newHead[0] < 0 || newHead[0] >= GRID_W || 
                newHead[1] < 0 || newHead[1] >= GRID_H) {
                gameState.alive = false;
                return;
            }

            for (let segment of gameState.snakeBody) {
                if (segment[0] === newHead[0] && segment[1] === newHead[1]) {
                    gameState.alive = false;
                    return;
                }
            }

            gameState.snakeBody.unshift(newHead);

            if (newHead[0] === gameState.food[0] && newHead[1] === gameState.food[1]) {
                gameState.score++;
                scoreDisplay.textContent = gameState.score;
                gameState.food = getNewFoodPosition();
            } else {
                gameState.snakeBody.pop();
            }

            draw();
        }

        function snake() {
            return gameState.snakeBody.map(segment => [...segment]);
        }

        function food() {
            return [...gameState.food];
        }

        function alive() {
            return gameState.alive;
        }

        function score() {
            return gameState.score;
        }

        function draw() {
            ctx.fillStyle = '#0a0a0a';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#00ff00';
            gameState.snakeBody.forEach((segment, index) => {
                const x = segment[0] * CELL_SIZE;
                const y = segment[1] * CELL_SIZE;
                ctx.fillStyle = index === 0 ? '#00ff00' : '#00cc00';
                ctx.fillRect(x + 1, y + 1, CELL_SIZE - 2, CELL_SIZE - 2);
            });

            ctx.fillStyle = '#ff0000';
            const foodX = gameState.food[0] * CELL_SIZE;
            const foodY = gameState.food[1] * CELL_SIZE;
            ctx.fillRect(foodX + 1, foodY + 1, CELL_SIZE - 2, CELL_SIZE - 2);
        }

        function startGame() {
            if (!gameState.alive || gameState.running) return;
            gameState.running = true;
            gameLoopId = setInterval(() => {
                tick();
                if (!gameState.alive) {
                    gameState.running = false;
                    clearInterval(gameLoopId);
                }
            }, 100);
        }

        function pauseGame() {
            gameState.running = false;
            if (gameLoopId) {
                clearInterval(gameLoopId);
                gameLoopId = null;
            }
        }

        document.getElementById('start').addEventListener('click', startGame);
        document.getElementById('pause').addEventListener('click', pauseGame);
        document.getElementById('reset').addEventListener('click', reset);

        document.addEventListener('keydown', (e) => {
            switch (e.key) {
                case 'ArrowUp':
                    setDir('up');
                    e.preventDefault();
                    break;
                case 'ArrowDown':
                    setDir('down');
                    e.preventDefault();
                    break;
                case 'ArrowLeft':
                    setDir('left');
                    e.preventDefault();
                    break;
                case 'ArrowRight':
                    setDir('right');
                    e.preventDefault();
                    break;
            }
        });

        window.game = {
            w: GRID_W,
            h: GRID_H,
            reset,
            tick,
            setDir,
            setFood,
            snake,
            food,
            alive,
            score
        };

        reset();
    </script>
</body>
</html>
